// Le scraper Python possède déjà la logique deux-passes : cap global (60),
// seuil hybride (10), déduplication par URL et normalisation 7 champs
// (source:indeed). Ici on se contente de parser sa sortie stdout (JSON array)
// et d'échouer proprement sur exit code != 0 (CAPTCHA / aucune offre).

const GLOBAL_CAP = 60;
const result = $input.first().json;
const exitCode = result.exitCode ?? result.returnCode ?? 0;
const stdout = (result.stdout ?? '').trim();
const stderr = (result.stderr ?? '').trim();

if (exitCode !== 0) {
  throw new Error(`indeed_scraper.py exit ${exitCode}: ${stderr.slice(-300)}`);
}

let offers = [];
try {
  offers = JSON.parse(stdout || '[]');
} catch (err) {
  throw new Error(`Sortie scraper non-JSON: ${stdout.slice(0, 200)}`);
}
if (!Array.isArray(offers)) offers = [];

// Dédup défensive par URL + cap (le scraper le fait déjà, ceinture+bretelles).
const seen = new Set();
const deduped = [];
for (const o of offers) {
  const url = o.url ?? '';
  if (url && !seen.has(url)) {
    seen.add(url);
    deduped.push(o);
  }
}
const capped = deduped.slice(0, GLOBAL_CAP);

return [{
  json: {
    offers:     capped,
    totalCount: capped.length,
    scanDate:   new Date().toISOString()
  }
}];
